        "Pick the project folder or the devcontainer.json itself": ["es": "Elige la carpeta del proyecto o el propio devcontainer.json", "pt": "Escolha a pasta do projeto ou o próprio devcontainer.json", "fr": "Choisissez le dossier du projet ou le devcontainer.json lui-même", "de": "Projektordner oder die devcontainer.json selbst auswählen", "uk": "Оберіть теку проєкту або сам devcontainer.json"],
